window.RG = window.RG || {};

RG.lawCategories = [
  { id: "sacrifice", name: "Sacrifice & Offerings", blurb: "The offerings, feasts of blood and fire, and rites of atonement that let a holy God and a fragile people share life together. Christians read them as pictures finally gathered up in the self-giving of Jesus (Hebrews 8–10)." },
  { id: "purity", name: "Purity & Impurity", blurb: "Laws about clean and unclean states: skin disease, bodily flows, contact with death. Impurity was usually not sin, but a condition that kept death and disorder away from the sanctuary. Jesus touched what was unclean, and it became clean." },
  { id: "food", name: "Food Laws", blurb: "What Israel could and could not eat, and how to treat blood. These laws marked Israel as a distinct people at every meal. The New Testament declares all foods clean while honouring the love that lay behind the rules (Mark 7:19; Acts 10; Romans 14)." },
  { id: "sabbath-feasts", name: "Sabbath & Feasts", blurb: "The rhythm of holy time: the weekly Sabbath, the seventh year, the Jubilee and the pilgrim festivals. Time itself became a teacher of rest, freedom and joy, and the New Testament sees Christ as the substance these shadows pointed to (Colossians 2:16–17)." },
  { id: "justice", name: "Justice & Mercy", blurb: "Laws for courts, debts, workers, the poor and the stranger. Many were remarkably humane for their world; some reflect the limits of their age. They show God bending an ancient society toward mercy." },
  { id: "worship", name: "Worship & Devotion", blurb: "How Israel was to honour God: no other gods, no images, reverence for the Name, priests, vows, and daily reminders of the covenant worn on the body and written on the doorposts." },
  { id: "family", name: "Family & Marriage", blurb: "Laws about marriage, divorce, inheritance and the protection of family lines in a tribal, patriarchal society. Some protected the vulnerable; others Jesus himself said were concessions to “the hardness of your hearts” (Mark 10:5)." },
  { id: "penal", name: "Penalties & Capital Laws", blurb: "Laws that carried severe punishments, including death. Read honestly, they belong to an ancient legal world, and Jesus' own handling of the Law calls Christians to read them through his mercy (John 8:1–11; Matthew 5:38–48)." },
  { id: "moral", name: "Love & the Moral Core", blurb: "Commands about honesty, faithfulness, life and desire, gathered up in the two great commands to love God and neighbour. Note: dividing the Law into ‘moral, civil and ceremonial’ is a later Christian scheme (Aquinas, Calvin); Jewish tradition counts 613 commandments without that split." },
  { id: "boundaries", name: "Boundaries & Distinctions", blurb: "Laws of separation: no mixed fabrics, no mixed seeds, signs on the body that set Israel apart from the nations. They taught a people to see the world as ordered and themselves as set apart. In Christ the dividing wall between peoples comes down (Ephesians 2:14)." }
];

RG.laws = [
  // ---------------- TEN COMMANDMENTS ----------------
  { id: "no-other-gods", name: "Ten Commandments 1: No Other Gods", category: "worship", ref: "Exodus 20:2–3; Deuteronomy 5:6–7",
    text: "“I am Yahweh your God, who brought you out of the land of Egypt, out of the house of bondage. You shall have no other gods before me.”",
    meaning: "The commands open not with a demand but with a rescue: God names himself as the one who freed slaves. In a world of many local and national gods, Israel was to give exclusive loyalty to Yahweh, much like a treaty bound a vassal to one great king. Scholars debate whether this first meant strict monotheism (no other gods exist) or monolatry (worship only one); the later prophets make the stronger claim plain (Isaiah 45:5). Traditions number the Ten differently: Jews count verse 2 as the first ‘word’, while Catholics and Lutherans combine this with the images command.",
    why: "Every other god Israel knew was tied to power, fertility and the state, and often to fear. Loyalty to the God who liberates protected Israel from being drawn back into the logic of Egypt. It shaped their identity around grace received before law given.",
    christ: "Jesus quotes the Shema as the first command (Mark 12:29–30) and reveals the one God as Father, Son and Spirit in a shared life of love (John 17:21). The God who ‘brought you out of bondage’ is seen fully in the one who frees us from sin and death (Luke 4:18; Galatians 5:1).",
    misuse: "The command has sometimes been turned into a license for violence against other faiths, or into a picture of a jealous tyrant, rather than the faithful love of a rescuer who wants his people free." },

  { id: "no-graven-images", name: "Ten Commandments 2: No Graven Images", category: "worship", ref: "Exodus 20:4–6; Deuteronomy 4:15–19",
    text: "“You shall not make for yourselves an idol, nor any image of anything that is in the heavens above, or that is in the earth beneath... you shall not bow yourself down to them, nor serve them.”",
    meaning: "In the Ancient Near East a cult statue was not just art; it was believed to house the god's presence. Mesopotamian texts describe a ‘mouth-washing’ ritual (mīs pî) to bring a statue to life so the god could dwell in it and be fed, clothed and managed. Israel was forbidden to make any image of Yahweh or other gods: God cannot be captured, carried off, or controlled. Deuteronomy 4 grounds it in Sinai: ‘you saw no form.’ The line about visiting iniquity ‘to the third and fourth generation’ is set against love ‘to thousands’, stressing that mercy far outruns judgment.",
    why: "An image gives worshippers a handle on God, a way to manipulate the divine. Forbidding images protected Israel from a religion of control and kept God free and personal. It also fits Genesis 1:26–27: God already has an image on earth, namely human beings.",
    christ: "The New Testament makes a startling claim: God has given his own image. Christ ‘is the image of the invisible God’ (Colossians 1:15) and whoever has seen him has seen the Father (John 14:9). We do not make God's image; God shows his face in Jesus, and that image is cruciform love, not a tool to wield. Every mental picture of God that does not look like Jesus is, in a sense, a graven image.",
    misuse: "Christians fought bitterly over icons: the Second Council of Nicaea (787) distinguished veneration from worship, while some Reformers smashed statues and windows. Both sides at times missed the deeper point: the most dangerous idols are false ideas of God, such as a violent or unloving deity." },

  { id: "name-in-vain", name: "Ten Commandments 3: Not Taking the Name in Vain", category: "worship", ref: "Exodus 20:7",
    text: "“You shall not take the name of Yahweh your God in vain, for Yahweh will not hold him guiltless who takes his name in vain.”",
    meaning: "Literally, ‘you shall not lift up (or carry) the name of Yahweh to emptiness.’ In its setting this most likely concerned false oaths sworn in God's name, using the name in magic or curses, and making empty vows. Some scholars also hear a wider sense: Israel ‘bears’ God's name before the nations and must not do so falsely.",
    why: "Courts and contracts relied on oaths, so false swearing destroyed trust and justice. Protecting God's name protected the truthfulness of the whole community, and guarded God's reputation among the nations.",
    christ: "Jesus goes further: let your yes be yes and your no be no (Matthew 5:33–37), since all speech is before God. He came ‘in his Father's name’ (John 5:43) and revealed that Name truly (John 17:6). Christians now carry his name, and the worst misuse is to attach it to cruelty.",
    misuse: "The command is often reduced to a ban on swearing words, while the far graver misuse, invoking God's name to bless war, abuse or greed, goes unchallenged." },

  { id: "sabbath-commandment", name: "Ten Commandments 4: Remember the Sabbath", category: "sabbath-feasts", ref: "Exodus 20:8–11; Deuteronomy 5:12–15",
    text: "“Remember the Sabbath day, to keep it holy. You shall labour six days, and do all your work, but the seventh day is a Sabbath to Yahweh your God. You shall not do any work in it, you, nor your son, nor your daughter, your male servant, nor your female servant...”",
    meaning: "The Sabbath was one of Israel's most distinctive practices: a seventh-day rest that included servants, foreigners and even animals. Exodus grounds it in creation (God rested on the seventh day), while Deuteronomy grounds it in liberation: ‘remember that you were a servant in Egypt.’ Babylonian texts mention a day called šapattu (the full-moon day), but a regular weekly rest for everyone has no clear parallel; the exact origins are debated. In a slave economy where Pharaoh demanded endless bricks, a weekly day off was a revolution.",
    why: "It protected the weak from exhaustion and exploitation, since even the slave and the ox rested. It trained Israel to trust that life is a gift, not something produced by endless work. And it marked time itself as holy, a weekly sign of the covenant (Exodus 31:13).",
    christ: "Jesus called himself ‘Lord of the Sabbath’ and said ‘the Sabbath was made for man, not man for the Sabbath’ (Mark 2:27–28); he healed on it deliberately to show its true purpose. Paul calls Sabbaths ‘a shadow of the things to come; but the body is Christ's’ (Colossians 2:16–17), and Hebrews 4:9–10 speaks of a rest that remains for God's people. In the relational reading, Jesus himself is our Sabbath: we rest in his finished work and share his rest with the weary (Matthew 11:28).",
    misuse: "Christians have kept it in very different ways: some (e.g. Seventh-day Adventists) hold to Saturday, many Protestants (e.g. the Westminster tradition) treat Sunday as the ‘Christian Sabbath’, and others see it fulfilled in Christ; this remains debated. Its misuse has come through harsh legalism, such as Puritan-era penalties and blue laws, which turned a gift of rest into a burden, the very thing Jesus challenged." },

  { id: "honour-parents", name: "Ten Commandments 5: Honour Father and Mother", category: "moral", ref: "Exodus 20:12; Deuteronomy 5:16",
    text: "“Honour your father and your mother, that your days may be long in the land which Yahweh your God gives you.”",
    meaning: "The Hebrew word for honour (kabed) comes from ‘heavy’: give your parents weight. In an agrarian world with no pensions, this was addressed mainly to adult children and meant caring for elderly parents, providing for them, and not shaming or abandoning them. Both mother and father are named, which was notable.",
    why: "Family was the social safety net; neglecting the old meant destitution for them. The command held the generations together and passed faith and memory down the line, which is why it is tied to long life in the land.",
    christ: "Jesus defended this command against a religious loophole (Corban) that let people dodge supporting their parents (Mark 7:9–13), and from the cross he provided for his mother (John 19:26–27). Paul calls it ‘the first commandment with a promise’ and also tells fathers not to provoke their children (Ephesians 6:1–4).",
    misuse: "It has been used to demand that children obey or stay silent about abusive parents. Honouring does not mean submitting to harm, and Jesus also said discipleship can put us at odds with family (Matthew 10:35–37)." },

  { id: "no-murder", name: "Ten Commandments 6: You Shall Not Murder", category: "moral", ref: "Exodus 20:13",
    text: "“You shall not murder.”",
    meaning: "The verb ratsach usually refers to unlawful killing of a person, often personal or blood-feud killing, rather than every kind of killing; the same Law also permits war and capital punishment. Its exact range is debated (it is also used of accidental manslaughter in Numbers 35). The deeper basis is Genesis 9:6: humans bear God's image.",
    why: "In a society without police, blood feuds could destroy whole clans. This command placed human life under God's protection and moved killing out of private vengeance and into limits and courts.",
    christ: "Jesus traced murder back to contempt and anger in the heart (Matthew 5:21–24) and called his followers to love enemies (Matthew 5:44). At the cross, humanity committed its worst killing and God answered with forgiveness (Luke 23:34). Relational-gospel writers (e.g. Brian Zahnd, Greg Boyd) see here a call to non-violence; many traditional Christians hold that just war and capital punishment remain permitted. That debate is real.",
    misuse: "Christians have often narrowed it to private murder while blessing crusades, inquisitions and wars of conquest, and sometimes drawn the circle of protected life very selectively." },

  { id: "no-adultery", name: "Ten Commandments 7: You Shall Not Commit Adultery", category: "moral", ref: "Exodus 20:14",
    text: "“You shall not commit adultery.”",
    meaning: "In the Ancient Near East adultery was defined mainly by the woman's marital status: sex between a married or betrothed woman and a man not her husband. A married man with an unmarried woman was treated differently, which reflects a patriarchal world where paternity and inheritance were at stake. Many law codes (e.g. Hammurabi) also punished it severely.",
    why: "It guarded the trust at the centre of family life, the security of children and the stability of inheritance. Covenant faithfulness in marriage also became Israel's chief image of God's own faithfulness (Hosea 2).",
    christ: "Jesus extended the command to the heart (Matthew 5:27–28) and applied it equally to men, removing the old double standard (Mark 10:11–12). When a woman caught in adultery was brought to him, he refused condemnation and said ‘go, and sin no more’ (John 8:1–11; note this passage is missing from the earliest manuscripts, though many think it a genuine memory of Jesus). Paul sees marriage as a picture of Christ's self-giving love (Ephesians 5:25–32).",
    misuse: "The church has often punished women far more harshly than men, and has sometimes treated sexual sin as the only sin, rather than one sign of a deeper loss of faithful love." },

  { id: "no-stealing", name: "Ten Commandments 8: You Shall Not Steal", category: "moral", ref: "Exodus 20:15",
    text: "“You shall not steal.”",
    meaning: "Theft of property was handled elsewhere with restitution, often double or more (Exodus 22:1–4), not prison. Some rabbinic interpreters (Talmud, Sanhedrin 86a) read the Decalogue's ‘steal’ as kidnapping, i.e. stealing a person, since Exodus 21:16 makes that a capital crime; this reading is debated.",
    why: "In a subsistence economy, losing an animal or tool could ruin a family. The command protected the means of life, and the restitution system aimed at repair rather than revenge.",
    christ: "Paul turns it into generosity: ‘let him who stole steal no more; but rather let him labour... that he may have something to give’ (Ephesians 4:28). Zacchaeus, met by Jesus, restores fourfold (Luke 19:8). In Christ the goal is not just ‘don't take’ but ‘share’ (Acts 2:44–45).",
    misuse: "It has sometimes been used to defend unjust wealth while ignoring the prophets' charge that exploiting the poor is itself theft (Isaiah 3:14–15; James 5:4)." },

  { id: "no-false-witness", name: "Ten Commandments 9: No False Witness", category: "moral", ref: "Exodus 20:16; Deuteronomy 19:15–21",
    text: "“You shall not give false testimony against your neighbour.”",
    meaning: "This was first a courtroom command. Cases were heard by elders at the city gate, often with no other evidence than testimony. The Law required at least two witnesses for a conviction, and a lying witness was to receive the penalty he tried to bring on his neighbour (Deuteronomy 19:19).",
    why: "When testimony is everything, one liar can destroy an innocent life. The command protected the weak from being framed by the powerful, as Naboth was (1 Kings 21).",
    christ: "Jesus himself was condemned by false witnesses (Mark 14:55–59), entering the place of every falsely accused person. He is ‘the faithful witness’ (Revelation 1:5) and calls the Spirit the Spirit of truth (John 16:13). Paul applies it broadly: ‘putting away falsehood, speak truth each one with his neighbour’ (Ephesians 4:25).",
    misuse: "Religious authorities have at times bent truth to protect institutions, including covering up abuse, which breaks this command in the very place it should be honoured most." },

  { id: "no-coveting", name: "Ten Commandments 10: You Shall Not Covet", category: "moral", ref: "Exodus 20:17; Deuteronomy 5:21",
    text: "“You shall not covet your neighbour's house... nor his male servant, nor his female servant, nor his ox, nor his donkey, nor anything that is your neighbour's.”",
    meaning: "The verb chamad means desire that fixes on something and often leads to scheming to get it (it is used of Achan in Joshua 7:21). Unusually for ancient law, it addresses an inner disposition that no court could prosecute. Deuteronomy's version lists the wife first and separately, and uses a second verb for craving, a small but notable shift.",
    why: "Coveting is the root of theft, adultery, false witness and even murder. Naming it protected neighbours and taught Israel that obedience starts in the heart, before it reaches the hands.",
    christ: "Paul says this command showed him the sin within (Romans 7:7–8), and that the Law could name desire but not heal it. Jesus warns against all covetousness, ‘for a man's life doesn't consist of the abundance of the things which he possesses’ (Luke 12:15). In union with Christ, the Spirit forms new desire: contentment and gift (Philippians 4:11–13).",
    misuse: "The list of ‘property’ includes a wife and servants, which some readers have used to treat women and workers as possessions. Read in light of Christ, the point is honouring the neighbour, not ranking people as goods." },

  // ---------------- SACRIFICES ----------------
  { id: "burnt-offering", name: "Burnt Offering (Olah)", category: "sacrifice", ref: "Leviticus 1; 6:8–13",
    text: "“He shall lay his hand on the head of the burnt offering, and it will be accepted for him to make atonement for him... the priest shall burn all on the altar, for a burnt offering... of a pleasant aroma to Yahweh.”",
    meaning: "The olah, ‘that which goes up’, was the one offering wholly burned on the altar, with no meat kept for priest or worshipper. It was offered every morning and evening for the nation and by individuals for devotion, vows, or atonement. The worshipper laid a hand on the animal, which scholars variously read as identification, ownership or transfer. The wording ‘pleasing aroma’ is common ancient sacrificial language, but Israel's God was not fed by it (Psalm 50:12–13).",
    why: "It let ordinary people give something costly and wholly to God, expressing total devotion in a form every ancient person understood. The daily fire kept the whole nation continually before God.",
    christ: "Hebrews 10:5–10 quotes Psalm 40: God did not desire sacrifices but prepared a body, and Christ offered himself once for all. Ephesians 5:2 speaks of Christ's self-giving love as ‘a sweet-smelling fragrance’, and Romans 12:1 invites us to be living offerings. The relational reading stresses self-giving love, not appeasing anger, as what made his offering ‘pleasing’; penal substitution views read it as satisfying God's justice. Both appeal to these texts.",
    misuse: "Some preaching has turned the altar into a picture of an angry deity who needs blood to calm down, which the prophets themselves resisted (Hosea 6:6; Micah 6:6–8)." },

  { id: "sin-offering", name: "Sin (Purification) Offering", category: "sacrifice", ref: "Leviticus 4:1–5:13; 6:24–30",
    text: "“If anyone sins unintentionally, in any of the things which Yahweh has commanded not to be done... let him offer for his sin which he has sinned a young bull without defect.”",
    meaning: "The chatta't is usually translated ‘sin offering’, but many scholars (notably Jacob Milgrom) argue ‘purification offering’ is closer: its blood was daubed on the altar or sanctuary to cleanse them from the defilement caused by sin and impurity. It covered mainly unintentional sins and certain impurities, such as after childbirth. The offering scaled to the person's means, from a bull down to birds or even flour for the poor (Leviticus 5:7–13). For defiant, high-handed sin there was no such offering (Numbers 15:30).",
    why: "It taught that wrongdoing, even unintended, damages the shared world and the place where God dwells, and that God provides a way to cleanse it. The sliding scale meant no one was too poor to be restored.",
    christ: "Hebrews 13:11–12 notes that sin-offering bodies were burned outside the camp, ‘therefore Jesus also... suffered outside of the gate.’ 2 Corinthians 5:21 is often read as God making Christ ‘a sin offering’ (some translations). In Christ, God himself provides the cleansing and draws near to the defiled rather than standing back from them.",
    misuse: "" },

  { id: "guilt-offering", name: "Guilt (Reparation) Offering", category: "sacrifice", ref: "Leviticus 5:14–6:7",
    text: "“He shall restore that which he took by robbery... and shall add a fifth part more to it. He shall give it to him to whom it belongs... and he shall bring his trespass offering to Yahweh.”",
    meaning: "The asham dealt with wrongs that caused loss, whether to holy things or to a neighbour through fraud, theft or false oath. It required full restitution plus a fifth (20%) to the injured party, and then a ram. Restoring the neighbour came before the altar.",
    why: "It built repair into worship: you could not be right with God while keeping what you had taken from your neighbour. It protected victims and made repentance concrete.",
    christ: "Isaiah 53:10 says the Servant makes his life an asham, a reparation offering, which the church applies to Jesus. Jesus echoes the order of this law: ‘first be reconciled to your brother, and then come and offer your gift’ (Matthew 5:23–24). Zacchaeus' restitution shows grace producing repair (Luke 19:8).",
    misuse: "Churches have sometimes preached forgiveness from God while skipping restitution to victims, the very thing this law insisted on." },

  { id: "peace-offering", name: "Peace / Fellowship Offering (Shelamim)", category: "sacrifice", ref: "Leviticus 3; 7:11–36",
    text: "“As for the flesh of the sacrifice of his peace offerings for thanksgiving, it shall be eaten on the day of his offering.”",
    meaning: "The shelamim (related to shalom) was shared: the fat went to God on the altar, a portion to the priest, and most of the meat was eaten by the worshipper with family and friends. It was offered for thanksgiving, to fulfil a vow, or freely. For most ordinary Israelites this was one of the few times they ate meat: a festive meal before God.",
    why: "It taught that worship is communion, not just transaction: God, priest and people eating together. It made joy and gratitude part of the sacrificial system.",
    christ: "Paul links the Lord's Supper to this kind of sacrificial meal: ‘aren't those who eat the sacrifices participants in the altar?’ (1 Corinthians 10:16–18). Christ ‘is our peace’ (Ephesians 2:14), and in him we eat at God's table. For the relational gospel this is the heart of sacrifice: not appeasement but shared life.",
    misuse: "" },

  { id: "passover-lamb", name: "Passover Lamb", category: "sacrifice", ref: "Exodus 12:1–14, 43–49",
    text: "“Your lamb shall be without defect, a male a year old... They shall take some of the blood, and put it on the two door posts and on the lintel... When I see the blood, I will pass over you.”",
    meaning: "Each household killed a lamb or kid at twilight, painted its blood on the doorframe, and ate it roasted with unleavened bread and bitter herbs, dressed to leave. It was not a sin offering in Leviticus' sense; the blood marked the household for protection on the night of deliverance. No bone was to be broken (Exodus 12:46), and the meal became the yearly memorial of freedom.",
    why: "It turned the founding rescue into a family meal that every generation would re-enact, with children asking ‘What does this mean?’ (Exodus 12:26). It forged Israel's identity as a freed people protected by God.",
    christ: "‘Christ, our Passover, has been sacrificed in our place’ (1 Corinthians 5:7). John's Gospel times the crucifixion with the slaughter of Passover lambs and notes that no bone of Jesus was broken (John 19:14, 36). Jesus reinterprets the Passover meal around his own body and blood (Luke 22:19–20): a new exodus from sin and death for all.",
    misuse: "Some early Christian preaching on Passover, notably Melito of Sardis' homily On Pascha, accused Israel of killing God, fuelling centuries of contempt for Jews. Later the fabricated ‘blood libel’ accused Jews of using Christian blood at Passover, a lie that led to massacres." },

  { id: "day-of-atonement", name: "Day of Atonement (Yom Kippur)", category: "sacrifice", ref: "Leviticus 16; 23:26–32",
    text: "“For on this day shall atonement be made for you, to cleanse you. You shall be clean from all your sins before Yahweh.”",
    meaning: "Once a year the high priest, after removing his glorious garments for plain linen, entered the Most Holy Place. He offered a bull for himself and his household, then took two goats: one ‘for Yahweh’ was killed and its blood sprinkled on and before the mercy seat (kapporet) to cleanse the sanctuary; the other was sent away (see the scapegoat). The people fasted and did no work. The Hebrew kipper is debated: ‘cover’, ‘wipe clean’, or ‘ransom’; in Leviticus 16 the stress is on purging the sanctuary and the people.",
    why: "A year of sin and impurity was thought to pollute the place of God's presence; this day reset everything so God could keep dwelling among them. It also gave the whole nation a shared day of humility and a fresh start.",
    christ: "Hebrews 9:11–14, 24–26 presents Christ as high priest who enters the true sanctuary ‘through his own blood’, once for all. Romans 3:25 calls him the hilastērion, the Greek word used for the mercy seat. The torn temple curtain (Mark 15:38) says the way into God's presence is open. Traditional readings stress Christ bearing judgment; relational readings stress God himself cleansing and opening the way into communion.",
    misuse: "" },

  { id: "scapegoat", name: "The Scapegoat (Goat for Azazel)", category: "sacrifice", ref: "Leviticus 16:8–10, 20–22",
    text: "“Aaron shall lay both his hands on the head of the live goat, and confess over him all the iniquities of the children of Israel... and shall send him away... into the wilderness.”",
    meaning: "Of the two goats chosen by lot, one was sacrificed and the other, ‘for Azazel’, was not killed but sent into the wilderness carrying the confessed sins. The meaning of ‘Azazel’ is genuinely uncertain: a name for a wilderness demon (as in later 1 Enoch), a word meaning ‘the goat that departs’ (hence ‘scapegoat’ from Tyndale's ‘escape goat’), or ‘a rugged place’. Similar elimination rites, sending away an animal to carry off evil, are known from Hittite and other ANE texts.",
    why: "The two goats gave a double picture: sin cleansed by blood, and sin carried far away (Psalm 103:12). It was a vivid, public way to say: it is gone.",
    christ: "Christians see Jesus as bearing away the sin of the world (John 1:29; Isaiah 53:6, 12) and suffering outside the camp (Hebrews 13:12). René Girard's influential (and debated) theory argues the cross exposes the human habit of scapegoating, with God siding with the victim; many relational-gospel writers draw on this. Traditional readings see the goat more simply as substitution.",
    misuse: "The word ‘scapegoat’ now names our habit of loading blame onto outsiders, and churches have done this to Jews, heretics and minorities, the opposite of the God who bears sin rather than blaming others." },

  { id: "red-heifer", name: "The Red Heifer", category: "sacrifice", ref: "Numbers 19",
    text: "“Tell the children of Israel that they bring you a red heifer without spot, in which is no defect, and which was never yoked.”",
    meaning: "A flawless red cow was slaughtered and wholly burned outside the camp with cedar wood, hyssop and scarlet yarn. Its ashes, mixed with running water, made the ‘water of purification’ sprinkled on those defiled by contact with a corpse. Strangely, those who prepared it became unclean themselves; the rabbis treated this as the classic example of a law whose reason is hidden.",
    why: "Death was the ultimate impurity, and everyone eventually touched it through family and burial. This rite gave a lasting way back from death's defilement into the community and the sanctuary.",
    christ: "Hebrews 9:13–14 argues: if the ashes of a heifer cleansed the flesh, ‘how much more will the blood of Christ... cleanse your conscience from dead works to serve the living God?’ Like the heifer, Jesus was put to death outside the gate and took on defilement to make others clean.",
    misuse: "In recent decades some groups have bred or imported red heifers hoping to restart temple sacrifice, and some Christian end-times teachers treat this as a countdown sign, turning a purity rite into speculation and political pressure around the Temple Mount." },

  { id: "firstborn-redemption", name: "Redemption of the Firstborn", category: "sacrifice", ref: "Exodus 13:1–2, 11–16; Numbers 3:40–51; 18:15–16",
    text: "“Sanctify to me all the firstborn... it is mine... All the firstborn of man among your sons you shall redeem.”",
    meaning: "Every firstborn male, of humans and animals, belonged to God. Clean animals were sacrificed, a donkey was redeemed with a lamb, and every firstborn son was ‘redeemed’ with a payment (later fixed at five shekels). The Levites were set apart for God's service in place of Israel's firstborn. Child sacrifice was practised by some neighbours (e.g. rites associated with Molech), and the Law sharply forbids it (Leviticus 18:21; Deuteronomy 12:31).",
    why: "It tied every family to the memory of the Passover night, when Egypt's firstborn died and Israel's were spared. It also declared, against the surrounding cultures, that God claims children in order to give them back, not to destroy them.",
    christ: "Mary and Joseph presented the infant Jesus according to this law (Luke 2:22–23). Christ is ‘the firstborn of all creation’ and ‘firstborn from the dead’ (Colossians 1:15, 18), the firstborn among many brothers and sisters (Romans 8:29): in him all are claimed by God and brought into the family.",
    misuse: "" },

  { id: "firstfruits", name: "Firstfruits", category: "sacrifice", ref: "Leviticus 23:9–14; Deuteronomy 26:1–11",
    text: "“You shall bring the sheaf of the first fruits of your harvest to the priest... A wandering Aramean was my father...”",
    meaning: "Before eating any new grain, Israel brought the first sheaf of barley to be waved before God. Deuteronomy 26 adds a basket of first produce brought to the sanctuary with a short creed recalling the patriarchs, Egypt and the gift of the land, followed by a feast shared with Levites and foreigners. Israel's neighbours also offered firstfruits to their gods, but here the offering is tied to history and gratitude rather than securing fertility.",
    why: "It taught that the land and its harvest were a gift, and that the first and best belongs to the Giver. Telling the story with the basket kept memory and identity alive.",
    christ: "‘Now Christ has been raised from the dead. He became the first fruits of those who are asleep’ (1 Corinthians 15:20, 23). His resurrection is the first sheaf of a whole harvest, which hopeful universalists like Thomas Talbott and David Bentley Hart read as embracing all humanity (1 Corinthians 15:22, 28); others limit it to believers. James 1:18 calls believers ‘a kind of first fruits’ of creation.",
    misuse: "Some prosperity teachers demand ‘firstfruits’ offerings (such as a month's wages) with promises of financial return, which misuses a thanksgiving rite as a transaction." },

  { id: "tithes", name: "The Tithes (Levite, Festival and Poor Tithes)", category: "sacrifice", ref: "Numbers 18:21–24; Deuteronomy 14:22–29; 26:12–13",
    text: "“You shall spend that money for whatever your soul desires: for cattle, or for sheep, or for wine, or for strong drink... and you shall eat there before Yahweh your God, and you shall rejoice, you and your household.” (Deuteronomy 14:26)",
    meaning: "The Torah describes several tenths of the produce. Numbers 18 gives a tithe to the Levites, who had no land (and they gave a tenth of it to the priests). Deuteronomy 14:22–27 describes a tithe that the giver himself ate at the sanctuary in a joyful feast with family and Levites; if the journey was long he could sell it and buy ‘whatever your soul desires’ there. Every third year the tithe was instead stored in the towns for the Levite, foreigner, orphan and widow (14:28–29). Later Jewish tradition harmonised these into a first tithe, a second (festival) tithe, and a poor tithe; many modern scholars think the texts reflect different periods' rules. Either way, a tithe was on crops and herds, not cash income.",
    why: "It funded worship, supported those without land, fed the poor, and taught Israel to celebrate. The festival tithe is a remarkable picture: God commands his people to feast and rejoice in his presence.",
    christ: "Jesus mentions tithing only to say the weightier matters are ‘justice, mercy, and faith’ (Matthew 23:23). The New Testament never commands a tithe for the church; instead it calls for cheerful, generous, proportionate giving (2 Corinthians 9:7) and shared life where no one is in need (Acts 4:34). In Christ everything is gift, so everything is shared.",
    misuse: "Malachi 3:8–10 (‘will a man rob God?’) is often used to pressure believers to give 10% of gross income to a church under threat of curse or promise of wealth. That ignores the festival and poor tithes and the New Testament's freedom of giving." },

  // ---------------- BOUNDARIES: CIRCUMCISION ----------------
  { id: "circumcision", name: "Circumcision", category: "boundaries", ref: "Genesis 17:9–14; Leviticus 12:3",
    text: "“This is my covenant, which you shall keep... every male among you shall be circumcised... He who is eight days old shall be circumcised among you.”",
    meaning: "Circumcision was practised by several ANE peoples, such as Egyptians (usually at puberty or before marriage), so the act itself was not unique. What marked Israel was its meaning as the sign of the covenant with Abraham and its timing on the eighth day, in infancy, before the child could do anything. Even within the Torah the deeper meaning is the heart: ‘circumcise the foreskin of your heart’ (Deuteronomy 10:16), which God promises to do himself (Deuteronomy 30:6).",
    why: "It marked Israel's men in their bodies as belonging to God's promise, generation after generation. It formed a clear identity boundary in a world where they could easily be absorbed by stronger nations.",
    christ: "Jesus was circumcised on the eighth day (Luke 2:21). The Jerusalem council decided Gentiles need not be circumcised (Acts 15), and Paul insists that ‘in Christ Jesus neither circumcision nor uncircumcision amounts to anything, but faith working through love’ (Galatians 5:6). Colossians 2:11–12 speaks of a ‘circumcision not made with hands’ in union with Christ's death and resurrection.",
    misuse: "Early on, some (the ‘Judaizers’) made it a requirement for salvation, which Paul fiercely resisted. Later Christian polemic turned Paul's arguments into contempt for Jewish practice itself, which Paul never intended (Romans 11:1, 28–29)." },

  // ---------------- FOOD ----------------
  { id: "clean-unclean-animals", name: "Clean and Unclean Animals", category: "food", ref: "Leviticus 11; Deuteronomy 14:3–21",
    text: "“Whatever parts the hoof, and is cloven-footed, and chews the cud among the animals, that you may eat.”",
    meaning: "Land animals had to both chew the cud and have split hooves; water creatures needed fins and scales; certain birds (mostly birds of prey and scavengers) and most insects were banned. Why these lines? Theories include hygiene (proposed partly by Maimonides, but many forbidden animals are safe to eat), Mary Douglas's influential theory that ‘clean’ animals fit their category neatly (she later revised her view), Jacob Milgrom's view that the laws limit killing and teach reverence for life, and identity: they simply set Israel apart. No single theory explains every detail.",
    why: "Every meal reminded Israel that they were set apart for God, and the rules made easy social mixing with idolatrous neighbours harder. As Leviticus 11:44–45 says: ‘be holy, for I am holy.’",
    christ: "Jesus taught that nothing entering a person from outside defiles them, and Mark adds: ‘thus he declared all foods clean’ (Mark 7:18–19). Peter's vision (Acts 10) taught him to call no person unclean, which opened the door to Gentiles. Paul: ‘nothing is unclean of itself’, yet we honour each other's consciences (Romans 14:14–21).",
    misuse: "Some Christians have turned these laws into a required health code, while others mocked Jewish observance. Both miss their purpose as a sign of a holy people, now fulfilled in a Table open to all." },

  { id: "pork", name: "No Pork", category: "food", ref: "Leviticus 11:7; Deuteronomy 14:8",
    text: "“The pig, because it has a split hoof, and is cloven-footed, but doesn't chew the cud, is unclean to you.”",
    meaning: "The pig fails the cud-chewing test. Archaeologists note that pig bones are rare at Iron Age Israelite highland sites but common at Philistine sites, and some (e.g. Israel Finkelstein) argue avoiding pork was an early ethnic marker; this remains debated. Pigs also appear in some pagan rites (Isaiah 65:4; 66:17). The trichinosis explanation is popular but weak, since many permitted animals carry risks too.",
    why: "Whatever its origin, avoiding pork became a strong mark of loyalty. When the Seleucid king Antiochus IV forced Jews to sacrifice and eat pigs, many chose death instead (1 Maccabees 1:47; 2 Maccabees 7).",
    christ: "Jesus sending demons into a herd of pigs (Mark 5:11–13) is set in Gentile territory, a sign he was entering ‘unclean’ space to liberate. The New Testament declares all foods clean (Mark 7:19; 1 Timothy 4:4).",
    misuse: "Christians have sometimes used pork to humiliate Jews, for example forcing converts in Spain and Portugal to eat it to prove sincerity." },

  { id: "shellfish", name: "No Shellfish", category: "food", ref: "Leviticus 11:9–12",
    text: "“All that don't have fins and scales in the seas, and in the rivers... they are an abomination to you.”",
    meaning: "Only fish with both fins and scales were permitted, so shellfish, eels and catfish were out. The word translated ‘abomination’ here is sheqets (detestable, to be avoided), which is a different word from to'evah used in Leviticus 18; how much should be built on that difference is debated. Israel was not a seafaring people, so this law mostly concerned freshwater and imported fish.",
    why: "Like the other food laws, it set Israel apart at the table and trained a sense of order and distinction. Some suggest bottom-dwelling creatures were associated with chaos and death, though this is speculative.",
    christ: "Jesus and Peter fished the lake and Jesus served fish (John 21:9–13); in his kingdom, food no longer divides (Mark 7:19; Romans 14:17: ‘the Kingdom of God is not eating and drinking, but righteousness, peace, and joy in the Holy Spirit’).",
    misuse: "In modern debates the ‘shellfish’ example is sometimes used carelessly on both sides: either to dismiss all biblical ethics or to pick and choose laws without explaining why. Honest reading asks how each law relates to Christ, not just which ones are convenient." },

  { id: "blood-prohibition", name: "Do Not Eat Blood", category: "food", ref: "Genesis 9:4; Leviticus 17:10–14; Deuteronomy 12:23–25",
    text: "“For the life of the flesh is in the blood. I have given it to you on the altar to make atonement for your souls.” (Leviticus 17:11)",
    meaning: "Blood was seen as the carrier of life itself, and life belongs to God. So animals had to be drained and the blood poured on the ground or used on the altar; eating it was strictly forbidden, even for foreigners living in Israel. Genesis 9 sets this before Israel, in the covenant with Noah, as a universal limit on killing.",
    why: "It taught reverence for life even when killing for food: you may eat, but the life is not yours. It also separated Israel from rites in which blood was consumed to gain power, and it set apart blood as God's means of cleansing.",
    christ: "The Jerusalem council kept abstaining from blood for Gentile believers, likely so Jews and Gentiles could share a table (Acts 15:20, 29). Strikingly, Jesus invites his followers to ‘drink my blood’ (John 6:53–56; Mark 14:23–24): the life God reserved for himself is now given to us. His life poured out becomes our life.",
    misuse: "Jehovah's Witnesses apply it to forbid blood transfusions, which most Christians see as a misreading of a food law. And Jews, who were forbidden blood more strictly than anyone, were falsely accused by Christians of ritual blood use (the ‘blood libel’)." },

  { id: "kid-in-mothers-milk", name: "Do Not Boil a Kid in Its Mother's Milk", category: "food", ref: "Exodus 23:19; 34:26; Deuteronomy 14:21",
    text: "“You shall not boil a young goat in its mother's milk.”",
    meaning: "This short law appears three times, but its original meaning is uncertain. Maimonides suggested it opposed a pagan ritual. In the 20th century a Ugaritic text (KTU 1.23, ‘Birth of the Gracious Gods’) was read as describing a kid cooked in milk, but the line is damaged and that reading is now widely doubted. Other explanations: it is a humane principle (like not taking a mother bird with her young, Deuteronomy 22:6–7) that refuses to mix life-giving milk with death, or a rule about the boundary between life and death. Rabbinic tradition expanded it into the full separation of meat and dairy.",
    why: "Whatever its exact origin, it taught tenderness toward the bond of mother and young, and that even ordinary cooking belongs within God's moral order.",
    christ: "The New Testament does not mention this law. Its spirit echoes in Jesus' image of God as a mother hen gathering her chicks (Luke 13:34) and his concern even for sparrows (Luke 12:6): God's holiness is full of tenderness.",
    misuse: "Popular teaching sometimes presents the Ugaritic ‘pagan ritual’ theory as proven fact; it is not." },

  // ---------------- PURITY ----------------
  { id: "skin-disease", name: "Skin Disease (Tsara'at) Laws", category: "purity", ref: "Leviticus 13–14",
    text: "“He shall dwell alone. His dwelling shall be outside of the camp.” (Leviticus 13:46)",
    meaning: "The Hebrew tsara'at is traditionally translated ‘leprosy’, but it is not the same as modern Hansen's disease; it covered a range of flaky or spreading skin conditions, and even mould in clothes and houses. The priest examined, waited and re-examined, but did not heal; his role was to declare clean or unclean. A person declared unclean lived outside the camp, tore their clothes and called out ‘unclean’, like a mourner. Restoration involved a striking two-bird rite, one bird killed and one set free (Leviticus 14:4–7).",
    why: "Visible decay looked like death, and impurity had to be kept from the sanctuary. The rules also had some public-health value by isolating spreading conditions, though their main logic was ritual, not medical. Importantly, the Law provided a way back.",
    christ: "Jesus did the unthinkable: he touched a man with leprosy, and instead of becoming unclean, he made the man clean (Mark 1:40–42), then sent him to the priest as the Law required. He healed ten lepers and praised the outsider who returned (Luke 17:11–19). Holiness in Jesus is contagious; it flows outward.",
    misuse: "Medieval society treated lepers as living dead and moral sinners, sometimes holding funeral rites for them. Christians have also used ‘uncleanness’ to stigmatise the sick, as happened in parts of the church during the AIDS crisis." },

  { id: "menstrual-impurity", name: "Menstrual Impurity (Niddah)", category: "purity", ref: "Leviticus 15:19–30; 18:19",
    text: "“If a woman has a discharge, and her discharge in her flesh is blood, she shall be in her impurity seven days.”",
    meaning: "Leviticus 15 treats both male and female genital discharges as causing ritual impurity, which passed by touch and ended after washing and time. Impurity was not sin; it was a normal condition, often linked to the loss of life-fluids, that simply meant one could not approach the sanctuary. A woman with ongoing bleeding remained unclean until it stopped and she brought a small offering.",
    why: "Blood and seed were associated with life and its loss, and these laws kept the realm of death and generation separate from God's holy space. They also gave women regular times of rest from sexual demands, though their main purpose was ritual.",
    christ: "A woman who had bled for twelve years touched the fringe of Jesus' cloak. He did not rebuke her for making him unclean; he called her ‘daughter’ and declared her healed and at peace (Mark 5:25–34). Her touch did not defile him; his life healed her.",
    misuse: "Some church traditions barred menstruating women from communion or church, and impurity ideas have been used to keep women from ministry. This reverses the very scene where Jesus welcomed the bleeding woman." },

  { id: "touching-the-dead", name: "Impurity from Touching the Dead", category: "purity", ref: "Numbers 19:11–22; Leviticus 21:1–4",
    text: "“He who touches the dead body of any man shall be unclean seven days.”",
    meaning: "Contact with a corpse, or even being in the same tent, caused the most serious impurity, lasting seven days and requiring sprinkling with the red heifer water on days three and seven. Priests were not to touch the dead except close family, and the high priest not even then. Unlike many neighbours, Israel did not have cults of feeding or consulting the dead (Deuteronomy 18:11; 26:14).",
    why: "Death is the opposite of the living God. Keeping death away from the sanctuary taught that God is the source of life, and shielded Israel from ancestor cults and necromancy common in the region.",
    christ: "Jesus touched the bier of a widow's son (Luke 7:14) and took a dead girl by the hand (Mark 5:41), and death fled. He entered death itself and rose, ‘the firstborn from the dead’ (Colossians 1:18). In the parable of the Good Samaritan, the priest and Levite pass by; whether purity concerns explain this is debated, but the point stands: love crosses lines (Luke 10:30–37).",
    misuse: "" },

  // ---------------- BOUNDARIES ----------------
  { id: "mixed-fabrics", name: "No Mixed Fabrics (Shaatnez)", category: "boundaries", ref: "Leviticus 19:19; Deuteronomy 22:11",
    text: "“You shall not wear clothing of wool and linen woven together.” (Deuteronomy 22:11)",
    meaning: "Ordinary Israelites were not to wear wool and linen woven together. Intriguingly, parts of the sanctuary curtains and the high priest's garments appear to have combined wool (dyed yarn) and linen (Exodus 26:1; 28:6; 39:29), as many scholars, including Jacob Milgrom, argue. If so, mixing was reserved for the holy: what was fitting for the sanctuary was not for everyday wear. Rabbinic law also allowed wool tassels on linen garments.",
    why: "It made holiness visible in daily life, teaching that some combinations belong only to God. It reinforced Israel's sense of an ordered world and of their own set-apart calling.",
    christ: "In Christ, all believers are a royal priesthood (1 Peter 2:9) and are ‘clothed with Christ’ (Galatians 3:27), so the priestly and the ordinary meet. The New Testament does not keep this law for Gentile believers; the separations it pictured find their goal in one new humanity (Ephesians 2:14–15).",
    misuse: "It is often mocked as an example of absurd biblical law, without seeing its link to priestly holiness. Others use it to wave away all of the Old Testament, rather than reading it through Christ." },

  { id: "mixed-seeds-cattle", name: "No Mixed Seeds or Cattle", category: "boundaries", ref: "Leviticus 19:19; Deuteronomy 22:9–10",
    text: "“You shall not let your livestock mate with a different kind of animal. You shall not sow your field with two kinds of seed.” “You shall not plow with an ox and a donkey together.”",
    meaning: "Israel was not to cross-breed animals, sow two kinds of seed in one field or vineyard, or yoke an ox with a donkey. These laws echo Genesis 1, where everything is made ‘after its kind.’ The ox and donkey law may also have been humane, since the two animals differ in strength and gait. Interestingly, Israel did use mules (2 Samuel 18:9), perhaps bought from abroad.",
    why: "Like the fabric law, it pictured an ordered creation and Israel's distinct calling. Daily farming became a reminder of holiness and, for the animals, perhaps kindness.",
    christ: "Paul likely echoes the yoke law in 2 Corinthians 6:14 (‘don't be unequally yoked’), applying it to partnership with idolatry. Yet in Christ, ethnic division ends: ‘there is neither Jew nor Greek’ (Galatians 3:28).",
    misuse: "In the 19th and 20th centuries some American and South African segregationists cited ‘after its kind’ and these mixing laws against interracial marriage, a grievous misuse with no basis in the text." },

  { id: "beard-corners", name: "Do Not Round the Corners of the Head or Beard", category: "boundaries", ref: "Leviticus 19:27; 21:5",
    text: "“You shall not cut the hair on the sides of your heads, neither shall you clip off the edge of your beard.”",
    meaning: "Shaving parts of the head or beard was a known mourning rite and sometimes a cultic practice among neighbouring peoples (Jeremiah 9:26; 48:37; Isaiah 15:2). The command sits beside the ban on cuts for the dead, so it likely refers to those customs. Later Jewish tradition developed side-locks (payot) from this verse.",
    why: "It kept Israel from adopting the mourning and religious rituals of surrounding cultures, often tied to cults of the dead. Even grief was to be expressed in a way that reflected hope in the living God.",
    christ: "The New Testament does not apply this law to Gentile believers. Christians grieve, but ‘not as the rest, who have no hope’ (1 Thessalonians 4:13), because Christ has risen.",
    misuse: "Some groups have used it to impose grooming rules on men as a test of holiness, missing its original link to pagan mourning rites." },

  { id: "marking-skin", name: "No Cuts or Marks for the Dead (Tattoos)", category: "boundaries", ref: "Leviticus 19:28; Deuteronomy 14:1",
    text: "“You shall not make any cuttings in your flesh for the dead, nor tattoo any marks on you. I am Yahweh.”",
    meaning: "Cutting oneself was a mourning rite and a way to rouse a god (see the prophets of Baal in 1 Kings 18:28). The second phrase uses a rare Hebrew word (qa'aqa) found only here; ‘tattoo’ is a reasonable guess, but its exact meaning is uncertain. In the ANE such marks could signal belonging to a deity or to an owner (slaves were sometimes marked). The context is clearly mourning and pagan devotion.",
    why: "Israel belonged to Yahweh alone and was not to bear the marks of other gods or the death cults. ‘You are the children of Yahweh your God’ (Deuteronomy 14:1) is the reason given: their bodies told whose they were.",
    christ: "Paul says ‘I bear the marks (stigmata) of the Lord Jesus branded on my body’ (Galatians 6:17), and believers are ‘sealed’ with the Spirit (Ephesians 1:13). Our belonging is now marked by the Spirit, not by skin.",
    misuse: "It is often used as a blanket ban on all modern tattoos, lifted out of its context of pagan mourning, while the rest of the chapter is ignored." },

  // ---------------- WORSHIP ----------------
  { id: "tassels-tzitzit", name: "Tassels on Garments (Tzitzit)", category: "worship", ref: "Numbers 15:37–41; Deuteronomy 22:12",
    text: "“Tell them that they should make themselves fringes on the borders of their garments throughout their generations, and that they put on the fringe of each border a cord of blue.” (Numbers 15:38)",
    meaning: "Israelite men were to wear tassels on the four corners of their outer garment, with a blue or violet thread. This dye (tekhelet) was made from sea snails and was very costly, worn by royalty and used in the sanctuary. Fringed hems signalled status in ANE art. So every Israelite wore a touch of royal and priestly colour.",
    why: "The stated purpose is memory: ‘that you may look on it, and remember all Yahweh's commandments’ (15:39). It dignified ordinary people as a holy, royal nation and guarded them from following their own impulses.",
    christ: "Jesus wore tassels: the bleeding woman and many sick people touched ‘the fringe (kraspedon) of his garment’ and were healed (Matthew 9:20; 14:36). He criticised those who enlarged their fringes for show (Matthew 23:5). In him, God's commands are written on the heart (Hebrews 8:10).",
    misuse: "Even in Jesus' day, symbols of devotion were used to display piety. Religious symbols in every tradition easily become badges of status rather than reminders of love." },

  { id: "tefillin-mezuzah", name: "Phylacteries and Doorposts (Tefillin & Mezuzah)", category: "worship", ref: "Deuteronomy 6:6–9; 11:18–20",
    text: "“You shall bind them for a sign on your hand, and they shall be for frontlets between your eyes. You shall write them on the door posts of your house and on your gates.”",
    meaning: "Following the Shema, Israel was told to keep God's words always present: on the hand, between the eyes, on doors and gates. Whether this was first meant metaphorically (like Proverbs 3:3, ‘bind them around your neck’) or literally is debated. By the Second Temple period it was practised literally: tefillin (small leather boxes holding scripture) have been found at Qumran, and the mezuzah case is fixed to Jewish doorposts to this day.",
    why: "It made faith part of daily life: work (hand), thought (eyes), and home (doors). It taught every generation that God's word is not only for the sanctuary but for kitchens and city gates.",
    christ: "Jesus names the Shema as the greatest command (Mark 12:29–30). He warned against making phylacteries broad for display (Matthew 23:5). The new covenant promise is that God writes his law on hearts (Jeremiah 31:33; 2 Corinthians 3:3), and Christ himself is the Word dwelling among us (John 1:14).",
    misuse: "In some periods both Jews and Christians treated such objects as magical amulets for protection, rather than reminders of loving God." },

  { id: "priestly-garments", name: "Priestly Garments and Priestly Holiness", category: "worship", ref: "Exodus 28; Leviticus 21",
    text: "“You shall make holy garments for Aaron your brother, for glory and for beauty.” (Exodus 28:2)",
    meaning: "The high priest wore an ephod, a breastpiece with twelve stones engraved with the tribes' names, the mysterious Urim and Thummim used for discerning God's will, and a gold plate on his turban reading ‘Holy to Yahweh.’ Priests had stricter rules for marriage, mourning and purity. Leviticus 21:16–23 also barred priests with physical defects from offering sacrifices (they could still eat the holy food), reflecting an ancient idea that what approaches God should be ‘whole’. This is hard for modern readers, and it should be named honestly.",
    why: "The garments displayed the dignity of serving God and showed the priest carrying the whole people on his heart before God (Exodus 28:29). The holiness rules marked the priest as a living sign of God's set-apart presence.",
    christ: "Hebrews presents Jesus as the great high priest who sympathises with our weakness (Hebrews 4:14–16) and is a priest ‘after the order of Melchizedek’, not by lineage (Hebrews 7). Now all believers are a ‘royal priesthood’ (1 Peter 2:9; Revelation 1:6). And Jesus welcomed the blind and lame to his table and into the temple (Matthew 21:14; Luke 14:13), undoing the exclusion.",
    misuse: "Churches have sometimes recreated a priestly caste that stands between God and people, and have used the ‘defect’ laws to exclude disabled people from ministry." },

  { id: "nazirite-vow", name: "The Nazirite Vow", category: "worship", ref: "Numbers 6:1–21",
    text: "“When either man or woman shall make a special vow, the vow of a Nazirite, to separate himself to Yahweh, he shall separate himself from wine and strong drink...”",
    meaning: "Any Israelite, man or woman, could take a vow of special devotion for a set time: no grape products at all, no cutting the hair, and no contact with the dead. At the end, the person offered sacrifices and shaved the head, burning the hair. Samson and Samuel were dedicated as lifelong Nazirites from birth (Judges 13; 1 Samuel 1:11).",
    why: "It gave ordinary people, including women, a way to live with priest-like devotion for a season. The long hair was a visible sign that their life was set apart.",
    christ: "Paul took a vow and shaved his head, and later paid for others completing Nazirite vows (Acts 18:18; 21:23–26). Jesus was not a Nazirite: he drank wine and touched the dead (Matthew 11:19; Luke 7:14). ‘Nazarene’ (from Nazareth) is a different word, though some think Matthew 2:23 plays on it. Jesus' holiness was shown not by separation but by drawing close.",
    misuse: "" },

  { id: "bronze-serpent", name: "The Bronze Serpent", category: "worship", ref: "Numbers 21:4–9; 2 Kings 18:4; John 3:14–15",
    text: "“Make a fiery serpent, and set it on a pole. It shall happen, that everyone who is bitten, when he sees it, shall live.” (Numbers 21:8)",
    meaning: "When venomous snakes struck the grumbling Israelites, God told Moses to make a bronze serpent on a pole; whoever looked at it lived. Serpent images were common symbols of healing and protection in the ANE, and a copper snake was found at a Midianite shrine at Timna near the Arabah, interesting context though not proof of anything about this story. Centuries later Israel was burning incense to this object, called Nehushtan, and King Hezekiah destroyed it (2 Kings 18:4).",
    why: "God used the very image of their affliction as the means of healing, asking only for a look of trust. It was a single instruction for a crisis, not an object to worship, as Hezekiah's action shows.",
    christ: "Jesus says: ‘As Moses lifted up the serpent in the wilderness, even so must the Son of Man be lifted up, that whoever believes in him should not perish, but have eternal life’ (John 3:14–15), followed by ‘God so loved the world’ (3:16). On the cross Christ became the image of our affliction (2 Corinthians 5:21) so that looking to him we live. He later says, ‘I, if I am lifted up, will draw all people to myself’ (John 12:32).",
    misuse: "The Nehushtan story itself shows the danger: a gift of God turned into a relic to be worshipped. Churches have done the same with relics and sacred objects." },

  // ---------------- SABBATH & FEASTS ----------------
  { id: "sabbath-year", name: "The Sabbath Year (Shemitah)", category: "sabbath-feasts", ref: "Exodus 23:10–11; Leviticus 25:1–7; Deuteronomy 15:1–11",
    text: "“At the end of every seven years, you shall cancel debts.” (Deuteronomy 15:1)",
    meaning: "Every seventh year the land was to lie fallow, and whatever grew on its own was for the poor, the stranger and wild animals. Deuteronomy adds the release of debts owed by fellow Israelites. Ancient Mesopotamian kings sometimes declared debt releases (mīšarum), but at a king's whim; Israel's was built into the calendar. The Bible suggests it was often neglected (2 Chronicles 36:21), and later the sage Hillel created the prosbul, a legal device allowing loans to survive the seventh year.",
    why: "It kept debt from turning into permanent poverty, gave the land rest, and taught trust that God would provide in the sixth year (Leviticus 25:20–22). Deuteronomy 15:4 dreams: ‘there will be no poor among you.’",
    christ: "Jesus' prayer ‘forgive us our debts, as we forgive our debtors’ (Matthew 6:12) echoes this release. His announcement of ‘release’ (aphesis, the same Greek word the Greek Old Testament uses for the release year) to captives (Luke 4:18) gathers up the Sabbath year into his mission. In Christ, forgiveness is God's great debt release.",
    misuse: "Christians have often spiritualised ‘forgiving debts’ completely, while allowing crushing financial debt among the poor to go unchallenged." },

  { id: "jubilee", name: "The Year of Jubilee", category: "sabbath-feasts", ref: "Leviticus 25:8–55",
    text: "“You shall make the fiftieth year holy, and proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee to you.” (Leviticus 25:10)",
    meaning: "After seven Sabbath-year cycles, the fiftieth year was announced by the ram's horn (yobel) on the Day of Atonement. Land sold under hardship returned to the original family, and Israelites in debt-servitude went free. Land could not be sold permanently, ‘for the land is mine; for you are strangers and live as foreigners with me’ (25:23). Whether the Jubilee was ever fully practised is uncertain; there is little historical evidence that it was.",
    why: "It stopped the slow drift of land into a few hands and gave every family a fresh start. It taught that the land is God's, and people are his guests and tenants.",
    christ: "Jesus' first sermon reads Isaiah 61, a Jubilee text: ‘to proclaim release to the captives... to proclaim the acceptable year of the Lord’ (Luke 4:18–19), and then says ‘today this Scripture has been fulfilled.’ In the relational gospel, Christ is the great Jubilee: humanity restored to its true inheritance in the Father.",
    misuse: "Some teachers promise personal financial ‘Jubilee’ breakthroughs for donors, while the text's call to economic justice for the poor is ignored. Others spiritualise it so fully that it has no practical meaning." },

  { id: "unleavened-bread", name: "Feast of Unleavened Bread", category: "sabbath-feasts", ref: "Exodus 12:15–20; Leviticus 23:6–8; Deuteronomy 16:3",
    text: "“Seven days you shall eat unleavened bread... the bread of affliction; for you came out of the land of Egypt in haste.” (Deuteronomy 16:3)",
    meaning: "For seven days after Passover Israel removed all leaven from their homes and ate only flat bread (matzah). It recalled the haste of leaving Egypt, with no time for dough to rise. It may also have been linked to the start of the barley harvest, a fresh beginning without old fermented dough.",
    why: "It made memory physical: every bite told the story of rescue. Clearing the house of leaven became a yearly picture of starting fresh.",
    christ: "Paul writes: ‘Purge out the old yeast, that you may be a new lump... For indeed Christ, our Passover, has been sacrificed in our place. Therefore let's keep the feast... with the unleavened bread of sincerity and truth’ (1 Corinthians 5:7–8). Jesus took this bread at the Last Supper and said ‘this is my body’ (Luke 22:19).",
    misuse: "" },

  { id: "shavuot", name: "Feast of Weeks (Shavuot / Pentecost)", category: "sabbath-feasts", ref: "Leviticus 23:15–21; Deuteronomy 16:9–12",
    text: "“You shall count from the next day after the Sabbath... seven Sabbaths shall be completed... fifty days; and you shall offer a new meal offering to Yahweh.” (Leviticus 23:15–16)",
    meaning: "Fifty days after the firstfruits sheaf, Israel celebrated the wheat harvest with two loaves baked with leaven, a rare exception to the ban on leaven at the altar. Deuteronomy commands rejoicing with servants, Levites, foreigners, orphans and widows. Later Jewish tradition linked Shavuot to the giving of the Law at Sinai; this connection is clear in rabbinic sources, and some earlier texts (like the book of Jubilees) tie the feast to covenant, but the timing of the link is debated.",
    why: "It celebrated harvest with thanks and generosity, and made sure the poor and outsiders shared the feast.",
    christ: "At Pentecost (Greek for ‘fiftieth’) the Spirit was poured out on the disciples, and people from many nations heard the gospel in their own languages (Acts 2). The law written on stone gives way to the Spirit writing on hearts (2 Corinthians 3:3); the two leavened loaves have been seen by some as a picture of Jew and Gentile together (a devotional reading, not stated in the text).",
    misuse: "" },

  { id: "feast-of-trumpets", name: "Feast of Trumpets", category: "sabbath-feasts", ref: "Leviticus 23:23–25; Numbers 29:1–6",
    text: "“In the seventh month, on the first day of the month, shall be a solemn rest to you, a memorial of blowing of trumpets, a holy convocation.”",
    meaning: "The first day of the seventh month was a day of rest marked by blasts of the shofar (ram's horn) or trumpets. The Torah says little about its meaning. In later Judaism it became Rosh Hashanah, the New Year, opening ten days of repentance before Yom Kippur. Trumpets in Israel announced kings, battles, gatherings and God's presence (Exodus 19:16).",
    why: "It summoned the people to attention at the start of the holiest month, preparing hearts for the Day of Atonement and the joy of Tabernacles.",
    christ: "The New Testament pictures the trumpet sounding at Christ's appearing and the resurrection of the dead (1 Corinthians 15:52; 1 Thessalonians 4:16; Matthew 24:31). It is the call of the King who comes to raise and gather.",
    misuse: "Many failed end-times predictions have set the rapture or return of Christ on the Feast of Trumpets (such as Edgar Whisenant's 1988 prediction), despite Jesus saying no one knows the day or hour (Matthew 24:36)." },

  { id: "tabernacles", name: "Feast of Tabernacles (Sukkot)", category: "sabbath-feasts", ref: "Leviticus 23:33–43; Deuteronomy 16:13–15",
    text: "“You shall dwell in booths seven days... that your generations may know that I made the children of Israel to dwell in booths, when I brought them out of the land of Egypt.” (Leviticus 23:42–43)",
    meaning: "At the end of the autumn harvest, Israel lived for a week in temporary shelters made of branches, and rejoiced. It recalled the wilderness years when God dwelt among them in a tent. Deuteronomy 16:14–15 commands joy and includes servants, foreigners, orphans and widows. By Jesus' time, the temple rites included water-pouring and great lamps lit in the courts (described in the Mishnah).",
    why: "It taught gratitude for harvest and humility: even in a settled land, they once lived in tents and depended on God. It was the most joyful feast of the year.",
    christ: "John says the Word ‘became flesh, and lived (literally tabernacled) among us’ (John 1:14). At this very feast Jesus cried, ‘If anyone is thirsty, let him come to me and drink!’ and said, ‘I am the light of the world’ (John 7:37–39; 8:12). Zechariah 14:16 pictures all nations keeping this feast, and Revelation 21:3 says ‘the tabernacle of God is with men.’",
    misuse: "" },

  // ---------------- JUSTICE ----------------
  { id: "gleaning", name: "Gleaning: Leave the Edges for the Poor", category: "justice", ref: "Leviticus 19:9–10; 23:22; Deuteronomy 24:19–22",
    text: "“When you reap the harvest of your land, you shall not wholly reap the corners of your field, neither shall you gather the gleanings of your harvest. You shall not glean your vineyard... You shall leave them for the poor and for the foreigner.”",
    meaning: "Farmers were to leave the edges of fields unharvested and not go back for dropped stalks, missed sheaves, or fallen grapes and olives. The poor, widows, orphans and foreigners could then gather food with dignity by their own work. The book of Ruth shows the system working, with Boaz going beyond the minimum (Ruth 2:15–16).",
    why: "It built a safety net into the economy itself, without shame or charity handouts. It reminded landowners that the harvest was God's gift and that they had once been strangers in Egypt (Deuteronomy 24:22).",
    christ: "Jesus' disciples plucked grain as they walked through fields, a practice the Law allowed (Deuteronomy 23:25; Mark 2:23); the dispute was only about the Sabbath. Ruth the Moabite gleaner became an ancestor of Jesus (Matthew 1:5). The early church's sharing with widows (Acts 6:1) carried on the same heart.",
    misuse: "Christians have sometimes treated generosity to the poor as optional charity rather than justice that God built into the order of things." },

  { id: "eye-for-eye", name: "Eye for an Eye (Lex Talionis)", category: "justice", ref: "Exodus 21:23–25; Leviticus 24:19–22; Deuteronomy 19:21",
    text: "“You shall give life for life, eye for eye, tooth for tooth, hand for hand, foot for foot.”",
    meaning: "This principle appears in older law codes too, such as the Code of Hammurabi, where penalties often depended on social class. In Israel it set a limit: punishment must fit the harm and not go beyond it, replacing endless revenge (compare Lamech's boast of seventy-sevenfold vengeance, Genesis 4:24). Leviticus 24:22 insists on one standard for native and foreigner. It was a rule for judges, not a license for private revenge, and Jewish tradition (e.g. the Talmud) understood it as monetary compensation; how literally it was applied in early Israel is debated.",
    why: "It stopped feuds from spiralling and protected the weak from disproportionate punishment by the strong. It was a step toward fairness in a violent world.",
    christ: "Jesus quotes it and then goes beyond it: ‘Don't resist him who is evil; but whoever strikes you on your right cheek, turn to him the other also’ (Matthew 5:38–39), and ‘love your enemies’ (5:44). Walter Wink's reading of the cheek-slap as non-violent resistance is a popular scholarly interpretation, not settled fact. Either way, the cross shows God answering harm with forgiveness, not equal payback.",
    misuse: "The phrase is often used to justify revenge, harsh punishment or war, the opposite of its original purpose as a limit, and of Jesus' teaching." },

  { id: "cities-of-refuge", name: "Cities of Refuge", category: "justice", ref: "Numbers 35:9–34; Deuteronomy 19:1–13; Joshua 20",
    text: "“You shall appoint cities to be cities of refuge for you, that the man slayer who kills any person unwittingly may flee there.”",
    meaning: "Six cities, spread across the land, offered protection to someone who killed another accidentally. In a culture where the victim's kin (the ‘avenger of blood’, go'el) was expected to take revenge, the killer could flee there and receive a hearing. If found innocent of intent, he stayed in the city until the death of the high priest, then could go home safely. Deliberate murderers were not protected.",
    why: "It separated accident from murder and put the blood feud under legal limits. It protected life on both sides, and the high priest's death marking release is a striking and much-discussed detail.",
    christ: "Hebrews 6:18 speaks of ‘we who have fled for refuge to take hold of the hope set before us.’ Early Christian writers saw the release at the high priest's death as a picture of Christ, our high priest, whose death sets the guilty free. In Christ, God becomes the refuge for all who flee to him.",
    misuse: "" },

  { id: "debt-slavery", name: "Slavery and Debt-Servant Laws", category: "justice", ref: "Exodus 21:1–11, 16, 20–27; Leviticus 25:39–55; Deuteronomy 15:12–18; 23:15–16",
    text: "“If you buy a Hebrew servant, he shall serve six years, and in the seventh he shall go out free without paying anything.” (Exodus 21:2)",
    meaning: "Most Israelite servitude was debt-servitude: a poor person sold their labour to pay debts. It was limited to six years, and Deuteronomy commands generous gifts on release. Kidnapping a person to sell was a capital crime (Exodus 21:16); a servant injured in the eye or tooth went free (21:26–27); runaway slaves were not to be returned (Deuteronomy 23:15–16), which was unusual in the ANE. But honesty matters: Leviticus 25:44–46 allows Israelites to buy foreigners as permanent slaves and pass them on as property; Exodus 21:7–11 lets a father sell his daughter as a servant-wife; and Exodus 21:20–21 punishes a master who beats a slave to immediate death but not if the slave survives a day or two, ‘for he is his property’.",
    why: "In a world without bankruptcy law or welfare, debt-servitude could be the alternative to starvation, and the Law worked to limit, soften and time-bound it. Many scholars see these laws as God meeting people within an existing system and pushing it toward mercy, rather than endorsing slavery as an ideal; others see more tension than that.",
    christ: "Jesus came ‘to proclaim release to the captives’ (Luke 4:18). Paul lists ‘enslavers’ among the lawless (1 Timothy 1:10), tells Philemon to receive Onesimus ‘no longer as a slave, but more than a slave, a beloved brother’ (Philemon 16), and declares ‘there is neither bond nor free... for you are all one in Christ Jesus’ (Galatians 3:28). Following the trajectory of Christ led many Christians, like the abolitionists, to oppose slavery entirely.",
    misuse: "In the American South and elsewhere, defenders of race-based chattel slavery quoted these laws and Paul's household codes to justify it. That system, built on kidnapping, was condemned by this very Law (Exodus 21:16)." },

  { id: "usury", name: "No Interest to Fellow Israelites", category: "justice", ref: "Exodus 22:25; Leviticus 25:35–37; Deuteronomy 23:19–20",
    text: "“If you lend money to any of my people with you who is poor, you shall not be to him as a creditor; neither shall you charge him interest.” (Exodus 22:25)",
    meaning: "Loans in ancient Israel were mostly emergency loans to the poor, not business investment. ANE interest rates could be very high (often 20% for silver and higher for grain). The Law forbade charging interest to fellow Israelites in need, though Deuteronomy 23:20 permits interest on loans to foreigners, likely traders.",
    why: "It kept a neighbour's crisis from becoming a profit opportunity and stopped debt from spiralling into slavery. It treated the community as family.",
    christ: "Jesus goes further: ‘lend, expecting nothing back; and your reward will be great’ (Luke 6:34–35). The early church shared possessions so no one was in need (Acts 4:34).",
    misuse: "The medieval church banned Christians from charging interest but let Jews do so, then stirred hatred against Jewish moneylenders, feeding stereotypes that lasted for centuries. Later many churches dropped all concern for predatory lending." },

  { id: "pledged-cloak", name: "Return a Pledged Cloak by Sunset", category: "justice", ref: "Exodus 22:26–27; Deuteronomy 24:10–13, 17",
    text: "“If you take your neighbour's garment as collateral, you shall restore it to him before the sun goes down, for that is his only covering... When he cries to me, I will hear, for I am gracious.”",
    meaning: "A poor man might give his outer cloak as security for a loan, but it was also his blanket at night. The lender had to return it each evening and could not enter the borrower's house to seize a pledge. A Hebrew inscription from Meṣad Ḥashavyahu (Yavneh-Yam, late 7th century BC) records a field worker pleading for the return of his confiscated garment, a vivid glimpse of the kind of abuse this law addressed. Amos condemned those who lay down on garments taken in pledge (Amos 2:8).",
    why: "It protected the poor from freezing and from humiliation, and gave the reason in God's own character: ‘I am gracious.’ God hears the cry of the one without a blanket.",
    christ: "Jesus says, ‘If anyone wants to sue you to take away your coat, let him have your cloak also’ (Matthew 5:40), a startling act that may have exposed the injustice of such suits (a debated reading). He himself was stripped of his garments at the cross (John 19:23–24), sharing the place of those who lose everything.",
    misuse: "" },

  { id: "same-day-wages", name: "Pay Wages the Same Day", category: "justice", ref: "Leviticus 19:13; Deuteronomy 24:14–15",
    text: "“In his day you shall give him his wages, neither shall the sun go down on it; for he is poor, and sets his heart on it.” (Deuteronomy 24:15)",
    meaning: "Day labourers lived hand to mouth, so withholding wages even overnight could mean a hungry family. The law applies to Israelite and foreign workers alike. Failing to pay brings guilt, because the worker may ‘cry to Yahweh against you.’",
    why: "It protected the most vulnerable workers and expressed God's attention to their cry. Justice included the timing of payment, not just the amount.",
    christ: "In Jesus' parable, the landowner pays the labourers at evening, and even the late arrivals receive a full day's wage (Matthew 20:1–16): grace beyond fairness. James warns, ‘the wages of the labourers who mowed your fields, which you have kept back by fraud, cry out’ (James 5:4).",
    misuse: "" },

  { id: "ox-muzzle", name: "Do Not Muzzle the Ox", category: "justice", ref: "Deuteronomy 25:4; 1 Corinthians 9:9–10; 1 Timothy 5:18",
    text: "“You shall not muzzle the ox when he treads out the grain.”",
    meaning: "Oxen walked over harvested grain on the threshing floor to separate it from the husk. Muzzling stopped them eating as they worked. This short law is placed among laws about human dignity and fairness, which has led some scholars to think it had a wider proverbial sense even in Deuteronomy.",
    why: "It taught kindness to working animals and, by extension, fairness to anyone who labours. Those who produce the harvest should share in it.",
    christ: "Paul applies it to apostles and teachers: ‘Is it for the oxen that God cares, or does he say it assuredly for our sake?’ (1 Corinthians 9:9–10). This is a ‘how much more’ argument like rabbinic qal va-chomer, not a denial that God cares for animals (Matthew 10:29). Strikingly, Paul then gives up his right to pay so the gospel would be free (9:12–18).",
    misuse: "Some leaders have used Paul's argument to justify lavish lifestyles, ignoring that Paul himself refused support to avoid burdening anyone." },

  { id: "roof-parapet", name: "Build a Parapet on Your Roof", category: "justice", ref: "Deuteronomy 22:8",
    text: "“When you build a new house, then you shall make a railing around your roof, so that you don't bring blood on your house if anyone falls from there.”",
    meaning: "Houses had flat roofs used as living space: for drying crops, sleeping in summer, and praying (Acts 10:9). A low wall or railing prevented deadly falls. If someone fell from an unguarded roof, the owner bore bloodguilt.",
    why: "It made safety a moral duty: we are responsible not only for what we do but for foreseeable harm we fail to prevent. It is an early building-safety code rooted in love of neighbour.",
    christ: "The New Testament does not cite it, but its spirit runs through Jesus' teaching that love seeks the good of the neighbour (Luke 10:27) and Paul's call not to put a stumbling block in another's path (Romans 14:13).",
    misuse: "" },

  { id: "welcome-foreigner", name: "Love the Foreigner", category: "justice", ref: "Leviticus 19:33–34; Exodus 22:21; 23:9; Deuteronomy 10:18–19",
    text: "“The stranger who lives as a foreigner with you shall be to you as the native-born among you, and you shall love him as yourself; for you lived as foreigners in the land of Egypt.” (Leviticus 19:34)",
    meaning: "The ger was a resident foreigner without land or clan protection. The Torah commands Israel more than thirty times to protect such people, include them in Sabbath rest and feasts, give them access to gleaning and the poor tithe, and judge them by one law (Numbers 15:16). The ger still had a distinct status in some laws, so this was not full equality in every respect.",
    why: "Israel's own story of oppression in Egypt was to shape their treatment of outsiders. And God himself ‘loves the foreigner, in giving him food and clothing’ (Deuteronomy 10:18).",
    christ: "Jesus was a refugee as a child (Matthew 2:13–15) and identifies himself with the stranger: ‘I was a stranger, and you took me in’ (Matthew 25:35). In Christ, Gentiles who were ‘strangers and foreigners’ become ‘fellow citizens with the saints’ (Ephesians 2:19). Hebrews 13:2 urges hospitality to strangers.",
    misuse: "Christians have often ignored this command when foreigners were seen as threats, and have sometimes used faith to stir hostility toward migrants." },

  { id: "king-laws", name: "Laws for the King", category: "justice", ref: "Deuteronomy 17:14–20; 1 Samuel 8",
    text: "“He shall not multiply horses to himself... Neither shall he multiply wives to himself... neither shall he greatly multiply to himself silver and gold... he shall write himself a copy of this law... that his heart not be lifted up above his brothers.”",
    meaning: "Unlike ANE kings who claimed divine status and wrote the laws, Israel's king was to be under the Law, ‘one from among your brothers’. He was not to build up chariot forces, a harem for political alliances, or great wealth, nor lead the people back to Egypt. He was to copy and read the Torah daily. Solomon broke every one of these rules (1 Kings 10:14–11:4). Samuel warned what kings would take (1 Samuel 8:10–18).",
    why: "It put limits on power and protected the people from tyranny. The ideal king was a brother and a student of God's word, not a master.",
    christ: "Jesus is the true king who comes riding a donkey, not a war horse (Matthew 21:5), who says ‘whoever wants to become great among you shall be your servant’ (Mark 10:42–45), and whose kingdom ‘is not of this world’ (John 18:36). He did not grasp at power but emptied himself (Philippians 2:6–8).",
    misuse: "Christian rulers have claimed ‘divine right’ and used faith to sanctify wealth, armies and empire, the very things this law forbade. Christian nationalism repeats the error by seeking power rather than the way of the cross." },

  // ---------------- FAMILY ----------------
  { id: "levirate-marriage", name: "Levirate Marriage and the Sandal Ceremony", category: "family", ref: "Deuteronomy 25:5–10; Genesis 38; Ruth 4",
    text: "“If brothers dwell together, and one of them dies, and has no son, the wife of the dead shall not be married outside to a stranger. Her husband's brother shall go in to her, and take her as his wife.”",
    meaning: "If a man died childless, his brother was to marry the widow so that a son could carry on the dead man's name and inheritance. If the brother refused, the widow could bring him before the elders, pull off his sandal and spit in his face: ‘So shall it be done to the man who does not build up his brother's house’ (25:9). Similar customs existed among Hittites and Assyrians. Tamar's story (Genesis 38) shows the injustice when a family refused, and Ruth 4 shows a related, wider custom of redemption sealed with a sandal.",
    why: "In a tribal land system, a widow without a son could be left without land, support or place. The custom protected her and preserved the family line, and the sandal ceremony gave a widow a rare public voice to shame a man who shirked his duty.",
    christ: "The Sadducees used this law to mock resurrection; Jesus replied that in the age to come relationships are transformed, and God ‘is not the God of the dead, but of the living’ (Mark 12:18–27). Both Tamar and Ruth, women at the heart of levirate stories, appear in Jesus' genealogy (Matthew 1:3, 5).",
    misuse: "" },

  { id: "kinsman-redeemer", name: "The Kinsman-Redeemer (Go'el)", category: "family", ref: "Leviticus 25:25, 47–49; Numbers 35:19; Ruth 3–4",
    text: "“If your brother becomes poor, and sells some of his possessions, then his kinsman who is next to him shall come, and redeem that which his brother has sold.” (Leviticus 25:25)",
    meaning: "The go'el was the nearest relative, responsible for rescuing family members in trouble: buying back land sold in poverty, buying a relative out of debt-servitude, and, in the case of murder, acting as ‘avenger of blood.’ Boaz acts as go'el for Naomi and Ruth. The prophets then call God himself Israel's Go'el, Redeemer (Isaiah 41:14; 43:14; Job 19:25).",
    why: "It made family responsible for rescuing family, so no one was simply lost to poverty or slavery. It gave Israel a powerful picture of God as a near relative who will not abandon his own.",
    christ: "For a redeemer to act, he had to be kin. Hebrews 2:11–17 says Christ shared our flesh and blood and ‘is not ashamed to call them brothers’; Galatians 4:4–5 says he was ‘born of a woman... that he might redeem.’ In the relational and Torrance tradition, the incarnation is exactly this: God becomes our kin so that he can redeem the whole human family from within.",
    misuse: "" },

  { id: "virgin-laws", name: "Bride Price and Virginity Laws", category: "family", ref: "Exodus 22:16–17; Deuteronomy 22:13–29",
    text: "“If a man finds a lady who is a virgin, who is not pledged to be married, and lays hold on her, and lies with her... the man who lay with her shall give to the lady's father fifty shekels of silver. She shall be his wife.” (Deuteronomy 22:28–29)",
    meaning: "Marriage involved a payment (mohar) from the groom's family to the bride's father. Deuteronomy 22 covers several cases: a husband accusing his bride of not being a virgin (if false, he is fined and can never divorce her; if ‘proven’, she is stoned); sex with a betrothed woman in the town (both stoned, presuming she could have cried out) or in the field (only the man dies, ‘for there is nothing in the young lady worthy of death’, 22:26); and sex with an unbetrothed virgin, where the man must pay and marry her and can never divorce her. Exodus 22:17 adds that the father may refuse the marriage. Honestly, these laws reflect a patriarchal world where a woman's sexuality was tied to family honour and value, and where she had little voice. Whether 22:28–29 describes rape or seduction is debated; the verb can mean ‘seize’.",
    why: "In that world, an unmarried woman who was not a virgin might never be married and could be left destitute. These laws forced men to take responsibility, protected brides from false accusation, and in the field case presumed the woman's innocence, more protective than some ANE codes. They also reveal the limits of their age and should not be called God's ideal for women.",
    christ: "Jesus treated women as full persons and disciples, defended a sinful woman against a judgmental host (Luke 7:36–50), and refused to condemn a woman accused of adultery (John 8:1–11). He revealed that the Law contained concessions to human hardness (Mark 10:5), and in him ‘there is neither male nor female’ (Galatians 3:28). The cruciform lens asks us to read these texts as part of a journey toward Christ, not its destination.",
    misuse: "These laws have been used to pressure victims of rape to marry their attackers, and in modern ‘purity culture’ to treat women's worth as their virginity. Both contradict Jesus' treatment of women." },

  { id: "divorce-certificate", name: "The Certificate of Divorce", category: "family", ref: "Deuteronomy 24:1–4; Mark 10:2–12; Matthew 19:3–9",
    text: "“When a man takes a wife, and marries her, then it shall be, if she finds no favour in his eyes, because he has found some unseemly thing in her, that he shall write her a certificate of divorce, put it in her hand, and send her out of his house.”",
    meaning: "The law assumes men could divorce and regulates it: a written certificate, put in her hand, freed her to remarry and protected her from accusations of adultery. The main command is actually narrow: the first husband could not remarry her after another marriage. ‘Some unseemly thing’ (‘ervat davar) was debated in Jesus' day: the school of Shammai said serious sexual wrongdoing, the school of Hillel allowed almost any reason.",
    why: "In a world where a man could simply throw out a wife, the certificate gave her legal proof of freedom and a chance to rebuild her life. It also discouraged swapping wives back and forth.",
    christ: "When asked about divorce, Jesus said: ‘For your hardness of heart, he wrote you this commandment. But from the beginning of the creation, God made them male and female’ (Mark 10:5–6). This is a key moment: Jesus himself says a law of Moses was a concession to human hardness, not God's ideal. Writers like Greg Boyd and Brad Jersak see this as a pattern for reading the whole Old Testament through Christ, while more traditional readers apply it only to this case.",
    misuse: "Churches have sometimes forced women to remain in abusive marriages by citing Jesus' words, and at other times have made divorce casual. Both forget his concern was protecting the vulnerable partner." },

  // ---------------- PENAL ----------------
  { id: "rebellious-son", name: "Stoning the Rebellious Son", category: "penal", ref: "Deuteronomy 21:18–21",
    text: "“If a man has a stubborn and rebellious son, who will not obey the voice of his father, or the voice of his mother... then his father and his mother shall take hold of him, and bring him out to the elders of his city... All the men of his city shall stone him to death.”",
    meaning: "This shocking law concerns a grown son described as ‘a glutton and a drunkard’ who persistently refuses correction. Notably, it takes the power of life and death away from the father alone (unlike Roman patria potestas): both parents must agree, and the case goes to the elders. The rabbis later surrounded it with so many conditions that the Talmud records the view that ‘there never was a stubborn and rebellious son and there never will be’ (Sanhedrin 71a); there is no biblical record of it being carried out.",
    why: "In a society where an adult son's dissolute life could ruin a family's land and endanger the community, it addressed a real threat. It also limited a father's private violence by requiring a public process.",
    christ: "Jesus' parable of the prodigal son tells of a son who squanders everything in wild living; instead of being stoned at the gate, his father runs to embrace him (Luke 15:11–32). Jesus himself was called ‘a glutton and a drunkard’ (Matthew 11:19), which many scholars hear as an echo of this law. In the cross, God bears the rebel's fate and welcomes him home.",
    misuse: "The Massachusetts Bay Colony's 1646 capital laws included the ‘stubborn or rebellious son’, though no execution is recorded. The text has also been used to justify harsh, violent parenting." },

  { id: "sabbath-breaker-death", name: "The Death Penalty for Sabbath-Breaking", category: "penal", ref: "Exodus 31:14–15; 35:2; Numbers 15:32–36",
    text: "“Everyone who does any work therein shall be put to death.” (Exodus 35:2)",
    meaning: "The Sabbath was the covenant sign, and Exodus treats deliberate violation as treason against the covenant. Numbers 15:32–36 tells of a man gathering sticks on the Sabbath; Moses asked God what to do, and the man was stoned. This narrative follows directly after the law about defiant, high-handed sin (15:30–31), suggesting it was seen as open rebellion, not a small slip.",
    why: "For a newly freed people, the Sabbath defined who they were: not slaves but God's people. Treating its violation as a capital matter protected the rest that safeguarded the weak, but it is one of the hardest laws for modern readers.",
    christ: "Jesus repeatedly healed on the Sabbath and was accused of breaking it; the authorities even plotted to kill him for it (Mark 3:1–6; John 5:16–18). He asked: ‘Is it lawful on the Sabbath day to do good, or to do harm? To save a life, or to kill?’ (Mark 3:4). In Jesus, the Sabbath becomes a day for healing, not a cause for death, and those who once punished Sabbath-breakers end up condemning the Lord of the Sabbath.",
    misuse: "Christian authorities in some times and places punished Sunday-breaking with fines, stocks or worse, turning a gift of rest into a weapon." },

  // ---------------- MORAL CORE ----------------
  { id: "love-god-shema", name: "Love God: The Shema", category: "moral", ref: "Deuteronomy 6:4–5; Mark 12:29–30",
    text: "“Hear, Israel: Yahweh is our God. Yahweh is one. You shall love Yahweh your God with all your heart, with all your soul, and with all your might.”",
    meaning: "The Shema (‘Hear!’) became Israel's central confession, still recited daily by observant Jews. ‘Yahweh is one’ can also be translated ‘Yahweh alone’; both senses fit. In ANE treaties, ‘love’ often meant loyalty to a great king, but here it is also deeply personal, involving heart (mind and will), soul (whole self) and strength.",
    why: "It gathered all the laws into one relationship: everything else flows from love for the God who loved them first (Deuteronomy 7:7–8). It shaped Israel's identity around devotion rather than mere rule-keeping.",
    christ: "Jesus names it the first and greatest command (Mark 12:29–30). Paul reworks the Shema to include Jesus: ‘one God, the Father... and one Lord, Jesus Christ’ (1 Corinthians 8:6). In the relational gospel, we love because he first loved us (1 John 4:19), and we are drawn by the Spirit into the Son's own love for the Father.",
    misuse: "Love for God has sometimes been set against love for people, used to justify cruelty in God's name. Scripture insists the two cannot be separated (1 John 4:20)." },

  { id: "love-neighbour", name: "Love Your Neighbour as Yourself", category: "moral", ref: "Leviticus 19:18; Mark 12:31; Romans 13:8–10",
    text: "“You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbour as yourself. I am Yahweh.”",
    meaning: "This command sits in the middle of Leviticus 19, among laws about gleaning, honest scales, wages and the disabled (19:14). In its immediate context ‘neighbour’ means a fellow Israelite, and it is set against revenge and grudges. Yet the same chapter extends the command to the foreigner: ‘you shall love him as yourself’ (19:34).",
    why: "It moved holiness out of the sanctuary and into everyday relationships. It made love, not just rule-keeping, the goal of the community's life.",
    christ: "Jesus joins it to the Shema as the second great command (Mark 12:31) and, asked ‘who is my neighbour?’, tells of a despised Samaritan who showed mercy (Luke 10:25–37), stretching ‘neighbour’ to everyone, even enemies (Matthew 5:43–44). Paul says ‘love is the fulfilment of the law’ (Romans 13:10; Galatians 5:14). Jesus' new command goes deeper still: ‘love one another, just like I have loved you’ (John 13:34).",
    misuse: "The church has at times narrowed ‘neighbour’ to its own members, repeating the very question Jesus answered with the Samaritan." }
];
